/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field TaxGroup
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableTaxGroup extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, TaxGroup);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    SalesTable salesTable;
    while select TaxGroup from salesTable
        group by TaxGroup
    {
        ret.add(salesTable.TaxGroup);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, TaxGroup));
    qbr.value(queryValue(_value));
}
